const APP_VERSION='v1.0.8';
const root=document.querySelector('#app');
const state={brand:{name:'MY.CO ENTERPRISES',logoUrl:'/logo.jpg'},token:localStorage.getItem('fishpos_token'),user:JSON.parse(localStorage.getItem('fishpos_user')||'null'),fish:[],categories:[],activeCategory:'all',cart:[],tab:'pos',clockTimer:null};
const money=n=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(Number(n)||0);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(url,opts={}){const h={...(opts.headers||{}),...(state.token?{Authorization:`Bearer ${state.token}`}:{})};if(opts.body&&!(opts.body instanceof FormData))h['Content-Type']='application/json';const r=await fetch(url,{...opts,headers:h});let d;try{d=await r.json()}catch{d=null}if(r.status===401){logout();throw Error(d?.error||'Please sign in again.')}if(!r.ok)throw Error(d?.error||'Request failed.');return d}
function applyBrand(){document.title=`${state.brand.name} · Fish Market POS`;const icon=document.querySelector('#siteFavicon');if(icon)icon.href=state.brand.logoUrl;document.querySelectorAll('[data-brand-logo]').forEach(img=>{img.src=state.brand.logoUrl;img.alt=`${state.brand.name} logo`});document.querySelectorAll('[data-brand-name]').forEach(el=>el.textContent=state.brand.name)}
async function loadBrand(){try{const response=await fetch('/api/brand');if(response.ok)state.brand=await response.json()}catch{}applyBrand()}
function brandSettingsMarkup(){return `<section class="panel brand-settings-panel" style="grid-column:1/-1"><div class="panel-head"><div><div class="eyebrow">BUSINESS IDENTITY</div><h2>Brand name and logo</h2></div></div><form id="brandForm" class="brand-settings-form"><label class="field"><span>Brand name</span><input name="brand_name" maxlength="100" required value="${esc(state.brand.name)}"></label><label class="field"><span>Logo image</span><input name="logo" type="file" accept="image/jpeg,image/png,image/webp,image/gif"><small class="muted">JPG, PNG, WEBP or GIF · max 5 MB</small></label><img class="brand-settings-preview" src="${esc(state.brand.logoUrl)}" alt="Current brand logo"><button class="btn btn-primary" type="submit">Save brand identity</button></form></section>`}
function setupBrandSettings(){const form=document.querySelector('#brandForm');if(!form)return;const preview=form.querySelector('.brand-settings-preview'),file=form.querySelector('[name=logo]');file.onchange=()=>{if(file.files[0])preview.src=URL.createObjectURL(file.files[0])};form.onsubmit=async e=>{e.preventDefault();const data=new FormData(form);if(!window.confirm(`Save brand identity as “${String(data.get('brand_name')).trim()}”?`))return;try{state.brand=await api('/api/brand',{method:'PUT',body:data});applyBrand();preview.src=state.brand.logoUrl;toast('Brand name and logo updated.')}catch(err){toast(err.message,true)}}}
let toastTimer;function toast(msg,error=false){const t=document.querySelector('#toast');t.textContent=msg;t.className=`toast show${error?' error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.className='toast',2800)}
function logout(){clearInterval(state.clockTimer);localStorage.removeItem('fishpos_token');localStorage.removeItem('fishpos_user');state.token=null;state.user=null;state.cart=[];renderLogin()}
function renderLogin(){root.innerHTML=`<div class="login-wrap"><section class="login-art"><div class="brand"><img class="brand-logo" data-brand-logo src="${esc(state.brand.logoUrl)}" alt="${esc(state.brand.name)} logo"><span data-brand-name>${esc(state.brand.name)}</span></div><div class="hero-copy"><span class="eyebrow" style="color:#a9d3cb">FARM FRESH. EVERDAY FRESH.</span><h1>Good mornings start at the fish counter.</h1><p>Your fresh, friendly point of sale for the fish market.</p></div><div class="login-note">Farm Fresh. Everday Fresh.</div><div class="fish-art">🐟</div></section><section class="login-panel"><form class="login-card" id="loginForm"><div class="eyebrow">MARKET COUNTER</div><h2>Welcome back</h2><p>Sign in to open your workspace.</p><label class="field"><span>Username</span><input name="username" autocomplete="username" required placeholder="Your username"></label><label class="field"><span>Password</span><input name="password" type="password" autocomplete="current-password" required placeholder="Your password"></label><div class="login-error" id="loginError"></div><button class="btn btn-primary btn-block">Sign in to POS</button><div class="app-version">Version ${APP_VERSION}</div></form></section></div>`;document.querySelector('#loginForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const d=await api('/api/login',{method:'POST',body:JSON.stringify({username:f.get('username'),password:f.get('password')})});state.token=d.token;state.user=d.user;localStorage.setItem('fishpos_token',d.token);localStorage.setItem('fishpos_user',JSON.stringify(d.user));await start()}catch(err){document.querySelector('#loginError').textContent=err.message}}}
async function start(){try{[state.fish,state.categories]=await Promise.all([api('/api/fish'),api('/api/categories')]);renderShell()}catch(e){toast(e.message,true)}}
function renderShell(){root.innerHTML=`<div class="shell"><header class="topbar"><div class="brand"><img class="brand-logo" data-brand-logo src="${esc(state.brand.logoUrl)}" alt="${esc(state.brand.name)} logo"><span data-brand-name>${esc(state.brand.name)}</span></div><nav class="nav"><button data-tab="pos" class="${state.tab==='pos'?'active':''}">Point of Sale</button>${['admin','shop_manager'].includes(state.user.role)?'<button data-tab="dashboard" class="'+(state.tab==='dashboard'?'active':'')+'">Dashboard</button>':''}<button data-tab="admin" class="'+(state.tab==='admin'?'active':'')+'">Management</button></nav><div class="header-clock"><span class="clock-symbol">◷</span><span id="headerClock"></span><small>GMT+8</small></div><div class="user-chip"><span class="avatar">${esc(state.user.username.slice(0,1).toUpperCase())}</span><span>${esc(state.user.username)}<small class="role" style="display:block">${state.user.role==='admin'?'Administrator':state.user.role==='shop_manager'?'Shop Manager':'Cashier'}</small></span></div><button class="btn btn-ghost" id="logout">Sign out</button></header><section class="main" id="content"></section></div>`;document.querySelector('#logout').onclick=logout;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;renderShell()});clearInterval(state.clockTimer);const updateClock=()=>{const el=document.querySelector('#headerClock');if(el)el.textContent=new Intl.DateTimeFormat('en-PH',{timeZone:'Asia/Manila',weekday:'short',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(new Date())};updateClock();state.clockTimer=setInterval(updateClock,1000);state.tab==='pos'?renderPOS():state.tab==='dashboard'?renderDashboard():renderManagement()}
function renderPOS(){const c=document.querySelector('#content');c.innerHTML=`<div class="page-head"><div><div class="eyebrow">${new Date().toLocaleDateString('en-PH',{weekday:'long',month:'long',day:'numeric'})}</div><h1>Point of Sale</h1><p>Choose a category, tap a fish, then enter the weight.</p></div><span class="badge">● Counter open</span></div><div class="pos-layout"><section class="catalog"><div class="catalog-head"><h2>Today's catch <span class="muted">(${state.fish.length})</span></h2><input class="search" id="fishSearch" placeholder="Search fish type…"></div><div class="category-tabs" id="categoryTabs"></div><div class="fish-grid" id="fishGrid"></div></section><aside class="basket"><div class="basket-top"><h2>Current sale</h2><span class="basket-count" id="basketCount">0 items</span></div><div class="scan-row"><input id="scanInput" placeholder="Scan barcode…" autocomplete="off"><button class="btn btn-light" id="scanBtn">Add</button></div><div class="scan-hint">Barcode scanner works as keyboard input. Press Enter to add.</div><div class="cart-lines" id="cartLines"></div><div class="total-row"><span>Sale total</span><strong id="total">₱0.00</strong></div><div class="notice">Prices are calculated from weight in kilograms. Confirm each weight before completing the sale.</div><button class="btn btn-primary btn-block" id="completeSale">Complete sale</button></aside></div>`;const grid=document.querySelector('#fishGrid'),tabs=document.querySelector('#categoryTabs');function drawCategories(){const hasUncategorized=state.fish.some(f=>!f.category_id);const options=[{id:'all',name:'All fish'},...state.categories,...(hasUncategorized?[{id:'uncategorized',name:'Uncategorized'}]:[])];if(!options.some(x=>String(x.id)===String(state.activeCategory)))state.activeCategory='all';tabs.innerHTML=options.map(x=>`<button type="button" class="category-tab ${String(state.activeCategory)===String(x.id)?'active':''}" data-category="${esc(x.id)}">${esc(x.name)}${x.id==='all'?` <span>${state.fish.length}</span>`:''}</button>`).join('');tabs.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{state.activeCategory=b.dataset.category;drawCategories();drawFish(document.querySelector('#fishSearch').value)})}function drawFish(filter=''){const rows=state.fish.filter(f=>{const matchesName=f.name.toLowerCase().includes(filter.toLowerCase());const matchesCategory=state.activeCategory==='all'||(state.activeCategory==='uncategorized'?!f.category_id:String(f.category_id)===String(state.activeCategory));return matchesName&&matchesCategory});grid.innerHTML=rows.length?rows.map(f=>`<article class="fish-card" data-fish="${f.id}"><div class="fish-thumb">${f.image_path?`<img src="${esc(f.image_path)}" alt="${esc(f.name)}">`:'🐟'}</div><div class="fish-info"><span class="fish-name">${esc(f.name)}</span><span class="fish-price">${money(f.price_per_kg)} <span class="muted">/ kg</span></span></div></article>`).join(''):'<div class="empty-state">No fish in this category yet.</div>';grid.querySelectorAll('[data-fish]').forEach(el=>el.onclick=()=>addFish(state.fish.find(f=>f.id==el.dataset.fish)))}drawCategories();drawFish();document.querySelector('#fishSearch').oninput=e=>drawFish(e.target.value);document.querySelector('#scanBtn').onclick=scanBarcode;document.querySelector('#scanInput').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();scanBarcode()}};document.querySelector('#completeSale').onclick=completeSale;drawCart()}function addFish(f){if(!f)return;state.cart.push({key:Math.random().toString(36).slice(2),fish:f,weight:''});drawCart();document.querySelector('#scanInput')?.focus()}
async function scanBarcode(){const input=document.querySelector('#scanInput');const code=input.value.trim();if(!code)return;try{const f=await api(`/api/fish/barcode/${encodeURIComponent(code)}`);addFish(f);input.value='';input.focus()}catch(e){toast(e.message,true);input.select()}}
function updateCartTotals(){const lines=document.querySelector('#cartLines');if(!lines)return;for(const x of state.cart){const line=lines.querySelector(`[data-line-total="${x.key}"]`);if(line)line.textContent=money((Number(x.weight)||0)*Number(x.fish.price_per_kg))}const total=state.cart.reduce((n,x)=>n+(Number(x.weight)||0)*Number(x.fish.price_per_kg),0);const totalEl=document.querySelector('#total');if(totalEl)totalEl.textContent=money(total)}
function drawCart(){const lines=document.querySelector('#cartLines');if(!lines)return;document.querySelector('#basketCount').textContent=`${state.cart.length} item${state.cart.length===1?'':'s'}`;if(!state.cart.length){lines.innerHTML='<div class="empty-cart">Your basket is ready.<br>Scan a barcode or choose a fish to begin.</div>';document.querySelector('#total').textContent=money(0);return}lines.innerHTML=state.cart.map(x=>`<div class="cart-line"><div class="cart-line-top"><span>${esc(x.fish.name)}</span><span data-line-total="${x.key}">${money((Number(x.weight)||0)*Number(x.fish.price_per_kg))}</span></div><div class="cart-line-sub">${money(x.fish.price_per_kg)} / kg</div><div class="weight-control"><input type="number" min="0.001" step="0.001" placeholder="0.000" value="${esc(x.weight)}" data-weight="${x.key}"><span>kg</span><button class="remove-line" data-remove="${x.key}">Remove</button></div></div>`).join('');lines.querySelectorAll('[data-weight]').forEach(i=>i.oninput=()=>{const x=state.cart.find(x=>x.key===i.dataset.weight);if(x){x.weight=i.value;updateCartTotals()}});lines.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{state.cart=state.cart.filter(x=>x.key!==b.dataset.remove);drawCart()});const total=state.cart.reduce((n,x)=>n+(Number(x.weight)||0)*Number(x.fish.price_per_kg),0);document.querySelector('#total').textContent=money(total)}
async function completeSale(){if(!state.cart.length)return toast('Add fish to the sale first.',true);if(state.cart.some(x=>!Number(x.weight)||Number(x.weight)<=0))return toast('Enter a weight in kg for every item.',true);const saleTotal=state.cart.reduce((sum,x)=>sum+Number(x.weight)*Number(x.fish.price_per_kg),0);const saleSummary=state.cart.map(x=>`${x.fish.name}: ${Number(x.weight).toFixed(3)} kg`).join('\n');if(!window.confirm(`Complete this sale?\n\n${saleSummary}\n\nTotal: ${money(saleTotal)}`))return;const button=document.querySelector('#completeSale');button.disabled=true;try{const sale=await api('/api/sales',{method:'POST',body:JSON.stringify({items:state.cart.map(x=>({fish_id:x.fish.id,weight_kg:Number(x.weight)}))})});state.cart=[];drawCart();toast(`Sale #${sale.id} complete · ${money(sale.total)}`);document.querySelector('#scanInput').focus()}catch(e){toast(e.message,true)}finally{button.disabled=false}}
function dateTimeLocal(date){const pad=n=>String(n).padStart(2,'0');return `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`}
function sqlUtcDateTime(value){if(!value)return '';const d=new Date(value);return Number.isNaN(d.getTime())?'':d.toISOString().slice(0,19).replace('T',' ')}
function renderDashboard(){
 const c=document.querySelector('#content');
 c.innerHTML=`<div class="dashboard-page"><div class="page-head dashboard-heading"><div><div class="eyebrow">MY.CO ENTERPRISES · BUSINESS OVERVIEW</div><h1>Sales dashboard</h1><p>See what’s selling, who’s serving, and how your market is doing.</p></div><div class="dashboard-live"><span></span> LIVE SALES INSIGHTS</div></div><section class="dashboard-filters"><div class="filter-intro"><strong>Explore your sales</strong><small>Choose a period and narrow the results.</small></div><label><span>Period</span><select id="dashPeriod"><option value="today">Today</option><option value="week" selected>Week to date</option><option value="month">Month to date</option><option value="year">Year to date</option><option value="custom">Custom range</option></select></label><label><span>From</span><input id="dashStart" type="datetime-local"></label><label><span>To</span><input id="dashEnd" type="datetime-local"></label><label><span>Category</span><select id="dashCategory"><option value="">All categories</option><option value="uncategorized">Uncategorized</option>${state.categories.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label><span>Cashier</span><select id="dashCashier"><option value="">All cashiers</option></select></label><button class="btn btn-primary" id="applyDashFilters">Apply filters</button><button class="btn btn-ghost" id="resetDashFilters">Reset</button></section><div id="dashboardResults"><div class="dashboard-loading">Loading your sales overview…</div></div></div>`;
 const period=document.querySelector('#dashPeriod'),cashierSelect=document.querySelector('#dashCashier');
 const setPeriod=p=>{const wall=new Date(Date.now()+8*60*60*1000),y=wall.getUTCFullYear(),m=wall.getUTCMonth(),day=wall.getUTCDate();let start=new Date(Date.UTC(y,m,day));if(p==='week')start.setUTCDate(start.getUTCDate()-(start.getUTCDay()+6)%7);else if(p==='month')start=new Date(Date.UTC(y,m,1));else if(p==='year')start=new Date(Date.UTC(y,0,1));document.querySelector('#dashStart').value=manilaWallDateTime(start.getTime()-8*60*60*1000);document.querySelector('#dashEnd').value=manilaWallDateTime(Date.now())};
 setPeriod('week');period.onchange=()=>{if(period.value!=='custom')setPeriod(period.value)};for(const id of ['dashStart','dashEnd'])document.querySelector(`#${id}`).oninput=()=>{period.value='custom'};
 api('/api/dashboard/options').then(options=>{cashierSelect.innerHTML='<option value="">All cashiers</option>'+options.cashiers.map(name=>`<option value="${esc(name)}">${esc(name)}</option>`).join('');loadDashboardData()}).catch(e=>{document.querySelector('#dashboardResults').innerHTML=`<div class="empty-state">${esc(e.message)}</div>`});
 document.querySelector('#applyDashFilters').onclick=loadDashboardData;document.querySelector('#resetDashFilters').onclick=()=>{document.querySelector('#dashCategory').value='';cashierSelect.value='';period.value='week';setPeriod('week');loadDashboardData()};
}
async function loadDashboardData(){const target=document.querySelector('#dashboardResults');if(!target)return;const params=new URLSearchParams();const from=sqlUtcDateTime(document.querySelector('#dashStart').value),to=sqlUtcDateTime(document.querySelector('#dashEnd').value);if(from)params.set('start',from);if(to)params.set('end',to);const category=document.querySelector('#dashCategory').value,cashier=document.querySelector('#dashCashier').value;if(category)params.set('category',category);if(cashier)params.set('cashier',cashier);target.innerHTML='<div class="dashboard-loading">Updating sales insights…</div>';try{const d=await api(`/api/dashboard?${params}`),m=d.metrics||{};const revenue=Number(m.revenue)||0,sales=Number(m.sale_count)||0,weight=Number(m.weight_kg)||0,average=Number(m.average_sale)||0;const rows=d.trendByCategory||[],dates=[...new Set(rows.map(x=>x.label))],categoryNames=[...new Set(rows.map(x=>x.category))],palette=['#4f963f','#eab94c','#e47b4b','#5889c4','#9a70bd','#dc6580','#46a89b','#8b9a43'],maxRevenue=Math.max(1,...rows.map(x=>Number(x.revenue)||0)),width=760,height=238,pad=38,series=categoryNames.map((name,i)=>({name,color:palette[i%palette.length],points:dates.map((label,idx)=>({label,x:dates.length<2?width/2:pad+idx*(width-pad*2)/(dates.length-1),y:height-pad-(Number(rows.find(x=>x.category===name&&x.label===label)?.revenue)||0)/maxRevenue*(height-pad*2),revenue:Number(rows.find(x=>x.category===name&&x.label===label)?.revenue)||0}))})),chart=dates.length?`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Daily sales by category">${[0,1,2,3].map(i=>`<line x1="${pad}" y1="${pad+i*(height-pad*2)/3}" x2="${width-pad}" y2="${pad+i*(height-pad*2)/3}" stroke="#e9eddf" stroke-dasharray="4 6"/>`).join('')}${series.map(s=>`<polyline points="${s.points.map(p=>`${p.x},${p.y}`).join(' ')}" fill="none" stroke="${s.color}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${s.points.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="4" fill="white" stroke="${s.color}" stroke-width="2"><title>${esc(s.name)} · ${esc(p.label)}: ${money(p.revenue)}</title></circle>`).join('')}`).join('')}</svg><div class="chart-axis"><span>${esc(dates[0])}</span><span>${esc(dates[Math.floor((dates.length-1)/2)])}</span><span>${esc(dates.at(-1))}</span></div><div class="chart-legend">${series.map(s=>`<span><i style="background:${s.color}"></i>${esc(s.name)}</span>`).join('')}</div>`:'<div class="empty-state">No sales in this time window yet.</div>';const bars=(items,color)=>{if(!items.length)return '<div class="empty-state">No sales data for this selection.</div>';const max=Math.max(1,...items.map(x=>Number(x.revenue)||0));return `<div class="dash-bars">${items.slice(0,7).map(x=>`<div class="dash-bar-row"><div><strong>${esc(x.name)}</strong><span>${money(x.revenue)}</span></div><div class="dash-bar-track"><i style="width:${Math.max(2,(Number(x.revenue)||0)/max*100)}%;background:${color}"></i></div></div>`).join('')}</div>`};target.innerHTML=`<section class="kpi-grid"><article class="kpi-card revenue-card"><div class="kpi-icon">₱</div><div class="kpi-label">Sales revenue</div><strong>${money(revenue)}</strong><small>Within selected filters</small></article><article class="kpi-card"><div class="kpi-icon">▣</div><div class="kpi-label">Transactions</div><strong>${sales.toLocaleString('en-PH')}</strong><small>Completed sales</small></article><article class="kpi-card"><div class="kpi-icon">↗</div><div class="kpi-label">Average sale</div><strong>${money(average)}</strong><small>Revenue per transaction</small></article><article class="kpi-card"><div class="kpi-icon">⚖</div><div class="kpi-label">Fish sold</div><strong>${weight.toLocaleString('en-PH',{maximumFractionDigits:3})} <small>kg</small></strong><small>By measured weight</small></article></section><section class="dashboard-grid"><article class="panel trend-panel"><div class="dash-panel-head"><div><div class="eyebrow">PERFORMANCE</div><h2>Daily sales by category</h2></div><span class="dash-unit">BY DAY</span></div><div class="trend-chart">${chart}</div></article><article class="panel breakdown-panel"><div class="dash-panel-head"><div><div class="eyebrow">PRODUCT MIX</div><h2>Sales by fish type</h2></div><span class="dash-glyph">🐟</span></div><div class="scroll-bars">${bars(d.fishTypes||[],'#eab94c')}</div></article><article class="panel breakdown-panel"><div class="dash-panel-head"><div><div class="eyebrow">TEAM PERFORMANCE</div><h2>Sales by cashier</h2></div><span class="dash-glyph">✳</span></div>${bars(d.cashiers,'#69a64a')}</article><article class="panel dash-recent"><div class="dash-panel-head"><div><div class="eyebrow">LATEST ACTIVITY</div><h2>Recent transactions</h2></div><span class="dash-unit">${d.recent.length} SHOWN</span></div>${d.recent.length?`<div class="dash-table-wrap"><table class="dash-table"><thead><tr><th>Transaction</th><th>Time</th><th>Cashier</th><th>Items</th><th>Total</th></tr></thead><tbody>${d.recent.slice(0,12).map(x=>`<tr><td><span class="sale-id">#${x.id}</span></td><td>${new Date(x.created_at).toLocaleString('en-PH',{dateStyle:'medium',timeStyle:'short'})}</td><td>${esc(x.cashier)}</td><td>${x.item_count}</td><td><strong>${money(x.filtered_total)}</strong></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">Transactions matching these filters will appear here.</div>'}</article></section>`}catch(e){target.innerHTML=`<div class="empty-state">${esc(e.message)}</div>`}}
function renderManagement(){if(state.user?.role==='admin')renderAdmin();else renderCashierManagement()}
function salesExportMarkup(){return `<div class="panel-head"><div><div class="eyebrow">REPORTS</div><h2>Export sales</h2><p class="muted" style="margin:5px 0 0;font-size:12px">Choose a period and optional filters, then download CSV or PDF.</p></div></div><div class="sales-export-controls"><label><span>Period</span><select id="exportPeriod"><option value="all">All time</option><option value="today">Today</option><option value="week">Week to date</option><option value="month">Month to date</option><option value="year">Year to date</option><option value="custom">Custom range</option></select></label><label><span>From (GMT+8)</span><input id="exportStart" type="datetime-local"></label><label><span>To (GMT+8)</span><input id="exportEnd" type="datetime-local"></label><label><span>Category</span><select id="exportCategory"><option value="">All categories</option><option value="uncategorized">Uncategorized</option></select></label>${state.user.role!=='cashier'?'<label><span>Cashier</span><select id="exportCashier"><option value="">All cashiers</option></select></label>':`<label><span>Cashier</span><div class="export-current-cashier">${esc(state.user.username)} · Your sales only</div></label>`}<div class="export-buttons"><button class="btn btn-primary" data-export-format="csv">Export CSV</button><button class="btn btn-light" data-export-format="pdf">Export PDF</button></div></div>`}
function manilaWallDateTime(epoch){const d=new Date(epoch+8*60*60*1000),pad=n=>String(n).padStart(2,'0');return `${d.getUTCFullYear()}-${pad(d.getUTCMonth()+1)}-${pad(d.getUTCDate())}T${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}`}
function manilaUtcDateTime(value){if(!value)return '';const d=new Date(`${value}:00+08:00`);return Number.isNaN(d.getTime())?'':d.toISOString().slice(0,19).replace('T',' ')}
function exportPresetRange(period){const wall=new Date(Date.now()+8*60*60*1000),y=wall.getUTCFullYear(),m=wall.getUTCMonth(),day=wall.getUTCDate();let start=new Date(Date.UTC(y,m,day,0,0,0));if(period==='week'){const sinceMonday=(start.getUTCDay()+6)%7;start.setUTCDate(start.getUTCDate()-sinceMonday)}else if(period==='month')start=new Date(Date.UTC(y,m,1,0,0,0));else if(period==='year')start=new Date(Date.UTC(y,0,1,0,0,0));document.querySelector('#exportStart').value=manilaWallDateTime(start.getTime()-8*60*60*1000);document.querySelector('#exportEnd').value=manilaWallDateTime(Date.now())}
function setupSalesExport(){const category=document.querySelector('#exportCategory'),cashier=document.querySelector('#exportCashier'),period=document.querySelector('#exportPeriod');if(!category||!period)return;api('/api/sales/export/options').then(options=>{const selected=category.value;category.innerHTML='<option value="">All categories</option><option value="uncategorized">Uncategorized</option>'+options.categories.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');category.value=selected;if(cashier){cashier.innerHTML='<option value="">All cashiers</option>'+options.cashiers.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}}).catch(e=>toast(e.message,true));period.onchange=()=>{if(period.value==='all'){document.querySelector('#exportStart').value='';document.querySelector('#exportEnd').value=''}else if(period.value!=='custom')exportPresetRange(period.value)};for(const id of ['exportStart','exportEnd'])document.querySelector(`#${id}`).oninput=()=>{period.value='custom'};document.querySelectorAll('[data-export-format]').forEach(button=>button.onclick=async()=>{const params=new URLSearchParams({format:button.dataset.exportFormat});const start=manilaUtcDateTime(document.querySelector('#exportStart').value),end=manilaUtcDateTime(document.querySelector('#exportEnd').value);if(start)params.set('start',start);if(end)params.set('end',end);if(category.value)params.set('category',category.value);if(cashier?.value)params.set('cashier',cashier.value);button.disabled=true;try{const response=await fetch(`/api/sales/export?${params}`,{headers:{Authorization:`Bearer ${state.token}`}});if(!response.ok){let data;try{data=await response.json()}catch{}throw Error(data?.error||'Could not export sales.')}const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');const disposition=response.headers.get('content-disposition')||'',filename=disposition.match(/filename="?([^";]+)"?/i)?.[1]||`myco-sales.${button.dataset.exportFormat}`;a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`${button.dataset.exportFormat.toUpperCase()} export downloaded.`)}catch(e){toast(e.message,true)}finally{button.disabled=false}})}
function renderCashierManagement(){const c=document.querySelector('#content');c.innerHTML=`<div class="page-head"><div><div class="eyebrow">${state.user.role==='shop_manager'?'SHOP MANAGER TOOLS':'CASHIER TOOLS'}</div><h1>Management</h1><p>${state.user.role==='shop_manager'?'Manage fish products and inventory, then export sales by cashier or overall.':'View fish products and inventory, print labels, or export your sales.'}</p></div></div><div class="admin-grid"><section class="panel" style="grid-column:1/-1"><div class="panel-head fish-panel-head"><div><div class="eyebrow">CATALOG</div><h2>Fish products & labels</h2></div><div class="fish-admin-actions"><div class="bulk-label-controls"><select id="bulkLabelMode"><option value="category">By category</option><option value="date">By date added</option></select><select id="bulkLabelCategory"><option value="all">All categories</option></select><input id="bulkLabelDate" type="date" style="display:none"><button class="btn btn-light" id="printBulkLabels">Print labels</button></div>${state.user.role==='shop_manager'?'<button class="btn btn-primary" id="cashierAddFish">＋ Add fish type</button>':''}</div></div><div style="overflow:auto"><table class="fish-table"><thead><tr><th>Fish</th><th>Category</th><th>Price / kg</th><th>Stock (kg)</th><th>Barcode</th><th>Date added</th><th>Label</th></tr></thead><tbody id="cashierFishRows"></tbody></table></div></section><section class="panel" style="grid-column:1/-1"><div class="panel-head"><h2>Inventory</h2><span class="muted">Stock is tracked in kilograms and reduced after each sale.</span></div><div style="overflow:auto"><table class="fish-table"><thead><tr><th>Fish</th><th>Category</th><th>Price / kg</th><th>Stock (kg)</th><th>Status</th><th>Actions</th></tr></thead><tbody id="inventoryRows"></tbody></table></div></section><section class="panel sales-export-panel" style="grid-column:1/-1">${salesExportMarkup()}</section></div>`;const body=document.querySelector('#cashierFishRows');body.innerHTML=state.fish.length?state.fish.map(f=>`<tr><td>${esc(f.name)}</td><td>${esc(f.category_name||'Uncategorized')}</td><td>${money(f.price_per_kg)}</td><td>${Number(f.stock_kg||0).toFixed(3)} kg</td><td>${esc(f.barcode_type||'EAN-13')} · ${esc(f.barcode)}</td><td>${new Date(f.created_at).toLocaleDateString('en-PH',{year:'numeric',month:'short',day:'numeric'})}</td><td><button class="small-btn" data-cashier-print="${f.id}">Print</button></td></tr>`).join(''):'<tr><td colspan="7" class="empty-state">No fish products yet.</td></tr>';body.querySelectorAll('[data-cashier-print]').forEach(b=>b.onclick=()=>printBarcode(b.dataset.cashierPrint));if(state.user.role==='shop_manager')document.querySelector('#cashierAddFish').onclick=()=>fishModal();setupBulkLabels();loadInventory();setupSalesExport()}
function renderAdmin(){const c=document.querySelector('#content');c.innerHTML=`<div class="page-head"><div><div class="eyebrow">ADMIN WORKSPACE</div><h1>Management</h1><p>Keep the catch list and team ready for service.</p></div></div><div class="admin-grid">${brandSettingsMarkup()}<section class="panel" style="grid-column:1/-1"><div class="panel-head fish-panel-head"><h2>Fish & pricing</h2><div class="fish-admin-actions"><div class="bulk-label-controls"><select id="bulkLabelMode" aria-label="Bulk label filter"><option value="category">By category</option><option value="date">By date added</option></select><select id="bulkLabelCategory" aria-label="Select category"><option value="all">All categories</option></select><input id="bulkLabelDate" type="date" aria-label="Date added" style="display:none"><button class="btn btn-light" id="printBulkLabels">Print labels</button></div><button class="btn btn-primary" id="addFish">＋ Add fish type</button></div></div><div style="overflow:auto"><table class="fish-table"><thead><tr><th>Fish</th><th>Category</th><th>Price / kg</th><th>Stock (kg)</th><th>Barcode</th><th>Date added</th><th>Actions</th></tr></thead><tbody id="fishRows"></tbody></table></div></section><section class="panel" style="grid-column:1/-1"><div class="panel-head"><h2>Inventory</h2><span class="muted">Stock is tracked in kilograms and reduced after each sale.</span></div><div style="overflow:auto"><table class="fish-table"><thead><tr><th>Fish</th><th>Category</th><th>Price / kg</th><th>Stock (kg)</th><th>Status</th><th>Actions</th></tr></thead><tbody id="inventoryRows"></tbody></table></div></section><section class="panel sales-export-panel" style="grid-column:1/-1">${salesExportMarkup()}</section><section class="panel"><div class="panel-head"><h2>Product categories</h2><button class="btn btn-light" id="addCategory">＋ Add category</button></div><div id="categoryList"></div></section><section class="panel"><div class="panel-head"><h2>Cashier accounts</h2><button class="btn btn-light" id="addUser">＋ Add user</button></div><div id="users"></div></section><section class="panel"><div class="panel-head"><h2>Admin account</h2></div><p class="muted">Change your own sign-in password.</p><button class="btn btn-light" id="changeAdminPassword">Change password</button></section><section class="panel"><div class="panel-head"><h2>Barcode labels</h2><span class="muted" style="font-size:11px">Admin only</span></div><div id="barcodeList"></div><p class="muted" style="font-size:10px;margin:12px 0 0">Print EAN-13 or UPC-A linear labels using your browser's print dialog. Both formats are supported by common barcode scanners.</p></section><section class="panel activity"><div class="panel-head"><h2>Recent sales</h2><button class="btn btn-light" id="refreshSales">Refresh</button></div><div id="salesList"></div></section></div>`;setupBrandSettings();drawFishRows();loadInventory();document.querySelector('#changeAdminPassword').onclick=passwordModal;document.querySelector('#addFish').onclick=()=>fishModal();setupBulkLabels();document.querySelector('#addCategory').onclick=()=>categoryModal();document.querySelector('#addUser').onclick=userModal;loadCategories();loadUsers();loadSales();setupSalesExport()}
function drawFishRows(){const body=document.querySelector('#fishRows');body.innerHTML=state.fish.length?state.fish.map(f=>`<tr><td><img class="fish-mini" src="${f.image_path?esc(f.image_path):''}" onerror="this.style.display='none'">${esc(f.name)}</td><td>${esc(f.category_name||'Uncategorized')}</td><td>${money(f.price_per_kg)}</td><td>${Number(f.stock_kg||0).toFixed(3)} kg</td><td><span class="badge">${esc(f.barcode_type||'EAN-13')} · ${esc(f.barcode)}</span></td><td>${new Date(f.created_at).toLocaleDateString('en-PH',{year:'numeric',month:'short',day:'numeric'})}</td><td><div class="table-actions"><button class="small-btn" data-edit="${f.id}">Edit</button><button class="small-btn delete" data-delete="${f.id}">Remove</button><button class="small-btn" data-print="${f.id}">Label</button></div></td></tr>`).join(''):'<tr><td colspan="7" class="empty-state">Add your first fish type to begin.</td></tr>';body.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>fishModal(state.fish.find(f=>f.id==b.dataset.edit)));body.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this fish from checkout? Past sales are kept.'))return;try{await api(`/api/fish/${b.dataset.delete}`,{method:'DELETE'});state.fish=await api('/api/fish');renderAdmin();toast('Fish type removed.')}catch(e){toast(e.message,true)}});body.querySelectorAll('[data-print]').forEach(b=>b.onclick=()=>printBarcode(b.dataset.print))}
function renderBulkCategoryOptions(){const select=document.querySelector('#bulkLabelCategory');if(!select)return;const selected=select.value;select.innerHTML='<option value="all">All categories</option><option value="uncategorized">Uncategorized</option>'+state.categories.map(cat=>`<option value="${cat.id}">${esc(cat.name)}</option>`).join('');if([...select.options].some(o=>o.value===selected))select.value=selected}
function localDateKey(value){const d=new Date(value);if(Number.isNaN(d.getTime()))return '';return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function setupBulkLabels(){const mode=document.querySelector('#bulkLabelMode'),category=document.querySelector('#bulkLabelCategory'),date=document.querySelector('#bulkLabelDate');renderBulkCategoryOptions();mode.onchange=()=>{const byDate=mode.value==='date';category.style.display=byDate?'none':'';date.style.display=byDate?'':'none'};document.querySelector('#printBulkLabels').onclick=async()=>{let selected;if(mode.value==='date'){if(!date.value)return toast('Choose a date added first.',true);selected=state.fish.filter(f=>localDateKey(f.created_at)===date.value)}else if(category.value==='uncategorized'){selected=state.fish.filter(f=>!f.category_id)}else if(category.value==='all'){selected=state.fish}else{selected=state.fish.filter(f=>String(f.category_id)===category.value)}if(!selected.length)return toast('No fish products match that selection.',true);if(selected.length>500)return toast('Bulk printing is limited to 500 labels at a time.',true);const w=window.open('','_blank','width=900,height=700');if(!w)return toast('Allow pop-ups to print barcode labels.',true);w.document.write('<!doctype html><title>Preparing labels…</title><p style="font:16px Arial;padding:24px">Preparing barcode labels…</p>');try{const result=await api('/api/fish/barcodes/print',{method:'POST',body:JSON.stringify({ids:selected.map(f=>f.id)})});w.document.open();w.document.write(result.html);w.document.close()}catch(e){w.close();toast(e.message,true)}}}
async function loadInventory(){try{const rows=await api('/api/inventory'),body=document.querySelector('#inventoryRows');if(!body)return;body.innerHTML=rows.map(f=>{const qty=Number(f.stock_kg||0);return `<tr><td>${esc(f.name)}</td><td>${esc(f.category_name||'Uncategorized')}</td><td>${money(f.price_per_kg)}</td><td><strong>${qty.toFixed(3)} kg</strong></td><td>${qty<=0?'<span class="badge">Out of stock</span>':qty<5?'<span class="badge">Low stock</span>':'<span class="badge">In stock</span>'}</td><td>${['admin','shop_manager'].includes(state.user.role)?`<button class="small-btn" data-add-kg="${f.id}" data-name="${esc(f.name)}">Add kg</button>${state.user.role==='admin'?` <button class="small-btn delete" data-remove-kg="${f.id}" data-name="${esc(f.name)}">Remove kg</button>`:''}`:'<span class="muted">View only</span>'}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty-state">Add fish products to track inventory.</td></tr>';body.querySelectorAll('[data-add-kg]').forEach(b=>b.onclick=async()=>{const value=window.prompt(`How many kilograms of ${b.dataset.name} are being added?`);if(value===null)return;const kg=Number(value);if(!Number.isFinite(kg)||kg<=0)return toast('Enter an amount greater than 0 kg.',true);if(!window.confirm(`Add ${kg.toFixed(3)} kg to ${b.dataset.name}?`))return;try{await api(`/api/inventory/${b.dataset.addKg}/add`,{method:'POST',body:JSON.stringify({kg})});state.fish=await api('/api/fish');loadInventory();drawFishRows();toast('Inventory increased.')}catch(e){toast(e.message,true)}});body.querySelectorAll('[data-remove-kg]').forEach(b=>b.onclick=async()=>{const value=window.prompt(`How many kilograms of ${b.dataset.name} should be removed from inventory?`);if(value===null)return;const kg=Number(value);if(!Number.isFinite(kg)||kg<=0)return toast('Enter an amount greater than 0 kg.',true);if(!window.confirm(`Remove ${kg.toFixed(3)} kg from ${b.dataset.name} inventory?\n\nThis action is for correcting a stock entry.`))return;try{await api(`/api/inventory/${b.dataset.removeKg}/remove`,{method:'POST',body:JSON.stringify({kg})});state.fish=await api('/api/fish');loadInventory();drawFishRows();toast('Inventory decreased.')}catch(e){toast(e.message,true)}})}catch(e){toast(e.message,true)}}
function passwordModal(){const m=showModal(`<form class="modal" id="passwordForm"><div class="modal-head"><div><div class="eyebrow">ADMIN ACCOUNT</div><h2 style="margin:4px 0 0">Change password</h2></div><button type="button" class="close">×</button></div><label class="field"><span>Current password</span><input name="current_password" type="password" autocomplete="current-password" required></label><label class="field"><span>New password</span><input name="new_password" type="password" minlength="8" autocomplete="new-password" required><small class="muted">At least 8 characters</small></label><label class="field"><span>Confirm new password</span><input name="confirm_password" type="password" minlength="8" autocomplete="new-password" required></label><div class="login-error" id="formError"></div><button class="btn btn-primary btn-block">Update password</button></form>`);m.querySelector('#passwordForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));if(data.new_password!==data.confirm_password){m.querySelector('#formError').textContent='New passwords do not match.';return}if(!window.confirm('Change your administrator password now?'))return;try{await api('/api/me/password',{method:'POST',body:JSON.stringify(data)});m.remove();toast('Administrator password changed.')}catch(err){m.querySelector('#formError').textContent=err.message}}}
async function loadCategories(){try{state.categories=await api('/api/categories');renderBulkCategoryOptions();const list=document.querySelector('#categoryList');if(!list)return;list.innerHTML=state.categories.map(cat=>`<div class="category-admin-row"><strong>${esc(cat.name)}</strong><span><button class="small-btn" data-edit-category="${cat.id}" data-category-name="${esc(cat.name)}">Rename</button> <button class="small-btn delete" data-delete-category="${cat.id}" data-category-name="${esc(cat.name)}">Remove</button></span></div>`).join('')||'<div class="empty-state">No categories yet.</div>';list.querySelectorAll('[data-edit-category]').forEach(b=>b.onclick=async()=>{const name=window.prompt('Rename category:',b.dataset.categoryName);if(!name||!name.trim())return;try{await api(`/api/categories/${b.dataset.editCategory}`,{method:'PUT',body:JSON.stringify({name:name.trim()})});[state.categories,state.fish]=await Promise.all([api('/api/categories'),api('/api/fish')]);loadCategories();drawFishRows();toast('Category renamed.')}catch(e){toast(e.message,true)}});list.querySelectorAll('[data-delete-category]').forEach(b=>b.onclick=async()=>{if(!window.confirm(`Remove category “${b.dataset.categoryName}”? Fish in it will become uncategorized.`))return;try{await api(`/api/categories/${b.dataset.deleteCategory}`,{method:'DELETE'});[state.categories,state.fish]=await Promise.all([api('/api/categories'),api('/api/fish')]);loadCategories();drawFishRows();toast('Category removed.')}catch(e){toast(e.message,true)}})}catch(e){toast(e.message,true)}}
function categoryModal(){const name=window.prompt('New category name:');if(!name||!name.trim())return;api('/api/categories',{method:'POST',body:JSON.stringify({name:name.trim()})}).then(async()=>{[state.categories,state.fish]=await Promise.all([api('/api/categories'),api('/api/fish')]);loadCategories();drawFishRows();toast('Category added.')}).catch(e=>toast(e.message,true))}
async function loadUsers(){try{const users=await api('/api/users');document.querySelector('#users').innerHTML=users.map(u=>`<div class="sale-row" style="grid-template-columns:1.2fr .7fr .7fr 1.2fr"><span><b>${esc(u.username)}</b></span><span>${esc(u.role)}</span><span>${u.active?'<span class="badge">Active</span>':'<span class="muted">Disabled</span>'}</span><span><button class="small-btn" data-toggle="${u.id}" data-active="${u.active}">${u.active?'Disable':'Enable'}</button>${['cashier','shop_manager'].includes(u.role)?` <button class="small-btn delete" data-remove-user="${u.id}" data-username="${esc(u.username)}">Remove</button>`:''}</span></div>`).join('')||'<div class="empty-state">No team accounts.</div>';document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=async()=>{try{await api(`/api/users/${b.dataset.toggle}`,{method:'PATCH',body:JSON.stringify({active:b.dataset.active!=='true'})});loadUsers();toast('Account updated.')}catch(e){toast(e.message,true)}});document.querySelectorAll('[data-remove-user]').forEach(b=>b.onclick=async()=>{if(!window.confirm(`Remove cashier account ${b.dataset.username}?\n\nThey will no longer be able to sign in. Past sales will retain the cashier name.`))return;try{await api(`/api/users/${b.dataset.removeUser}`,{method:'DELETE'});loadUsers();loadSales();toast('Cashier account removed.')}catch(e){toast(e.message,true)}})}catch(e){toast(e.message,true)}}
async function loadSales(){try{const sales=await api('/api/sales');const el=document.querySelector('#salesList');el.innerHTML=sales.length?'<div class="sale-row header"><span>Sale</span><span>Cashier</span><span>Total</span><span>Items</span></div>'+sales.map(s=>`<div class="sale-row"><span>#${s.id} · ${new Date(s.created_at).toLocaleString('en-PH',{dateStyle:'short',timeStyle:'short'})}</span><span>${esc(s.cashier||'—')}</span><b>${money(s.total)}</b><span>${s.items.map(i=>`${esc(i.name)} ${Number(i.weight_kg).toFixed(3)}kg`).join(', ')}</span></div>`).join(''):'<div class="empty-state">Sales will appear here after checkout.</div>';document.querySelector('#refreshSales').onclick=loadSales}catch(e){toast(e.message,true)}}
function showModal(html){const el=document.createElement('div');el.className='overlay';el.innerHTML=html;document.body.appendChild(el);el.onclick=e=>{if(e.target===el)el.remove()};el.querySelector('.close').onclick=()=>el.remove();return el}
function fishModal(f){const edit=!!f;const m=showModal(`<form class="modal" id="fishForm"><div class="modal-head"><div><div class="eyebrow">CATALOG</div><h2 style="margin:4px 0 0">${edit?'Edit fish type':'Add fish type'}</h2></div><button type="button" class="close">×</button></div><div class="form-grid"><label class="field wide"><span>Fish name</span><input name="name" required maxlength="80" value="${esc(f?.name||'')}" placeholder="e.g. Bangus"></label><label class="field"><span>Category</span><select name="category_id"><option value="">Uncategorized</option>${state.categories.map(cat=>`<option value="${cat.id}" ${String(f?.category_id||'')===String(cat.id)?'selected':''}>${esc(cat.name)}</option>`).join('')}</select></label><label class="field"><span>Price per kilogram (₱)</span><input name="price_per_kg" type="number" min="0" step="0.01" required value="${esc(f?.price_per_kg||'')}" placeholder="0.00"></label>${edit?'':`<label class="field"><span>Starting inventory (kg)</span><input name="stock_kg" type="number" min="0" step="0.001" value="0" required></label>`}<label class="field"><span>Barcode format</span><select name="barcode_type" id="barcodeType"><option value="EAN-13" ${(!f?.barcode_type||f?.barcode_type==='EAN-13')?'selected':''}>EAN-13</option><option value="UPC-A" ${f?.barcode_type==='UPC-A'?'selected':''}>UPC-A</option></select></label><label class="field"><span>Barcode number</span><input name="barcode" id="barcodeNumber" inputmode="numeric" maxlength="${f?.barcode_type==='UPC-A'?12:13}" value="${esc(f?.barcode||'')}" placeholder="Leave blank to generate ${f?.barcode_type||'EAN-13'}"></label><label class="field wide"><span>Fish image</span><div class="upload-box">JPG, PNG, WEBP or GIF · max 5 MB<input name="image" type="file" accept="image/jpeg,image/png,image/webp,image/gif"></div></label></div><div class="login-error" id="formError"></div><button class="btn btn-primary btn-block">${edit?'Save changes':'Add fish type'}</button></form>`);const barcodeTypeInput=m.querySelector('#barcodeType'),barcodeNumberInput=m.querySelector('#barcodeNumber');barcodeTypeInput.onchange=()=>{barcodeNumberInput.value='';barcodeNumberInput.maxLength=barcodeTypeInput.value==='EAN-13'?13:12;barcodeNumberInput.placeholder=`Leave blank to generate ${barcodeTypeInput.value}`};m.querySelector('#fishForm').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.currentTarget);if(!form.get('barcode'))form.delete('barcode');const actionName=String(form.get('name')||'').trim();const price=Number(form.get('price_per_kg'));const barcodeType=String(form.get('barcode_type')||'EAN-13');const stock=Number(form.get('stock_kg')||0);const message=edit?'Save changes to this fish type?':'Add this fish product? If the fish type already exists, the entered kilograms will be added to its inventory instead of creating a duplicate.';if(!window.confirm(`${message}\n\n${actionName}\nPrice: ${money(price)} / kg\nBarcode: ${barcodeType} (generated if left blank)${edit?'':`\nStock to add: ${stock.toFixed(3)} kg`}`))return;try{const result=await api(edit?`/api/fish/${f.id}`:'/api/fish',{method:edit?'PUT':'POST',body:form});[state.fish,state.categories]=await Promise.all([api('/api/fish'),api('/api/categories')]);m.remove();renderManagement();toast(edit?'Fish type updated.':result.existing?'Existing fish found; inventory increased.':'Fish type added.')}catch(err){m.querySelector('#formError').textContent=err.message}}}
function userModal(){const m=showModal(`<form class="modal" id="userForm"><div class="modal-head"><div><div class="eyebrow">TEAM ACCESS</div><h2 style="margin:4px 0 0">Add team member</h2></div><button type="button" class="close">×</button></div><label class="field"><span>Username</span><input name="username" required minlength="3" autocomplete="off"></label><label class="field"><span>Temporary password</span><input name="password" required minlength="8" type="password" autocomplete="new-password"><small class="muted">At least 8 characters</small></label><label class="field"><span>Role</span><select name="role"><option value="cashier">Cashier · checkout access</option><option value="admin">Admin · full access</option><option value="shop_manager">Shop Manager · products, inventory & sales</option></select></label><div class="login-error" id="formError"></div><button class="btn btn-primary btn-block">Create account</button></form>`);m.querySelector('#userForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));if(!window.confirm(`Create this ${data.role} account?\n\nUsername: ${data.username}\nAccess: ${data.role==='admin'?'Full admin access':data.role==='shop_manager'?'Products, inventory, and sales exports':'Checkout only'}`))return;try{await api('/api/users',{method:'POST',body:JSON.stringify(data)});m.remove();loadUsers();toast('Account created.')}catch(err){m.querySelector('#formError').textContent=err.message}}}
async function printBarcode(id){const w=window.open('','_blank','width=440,height=360');if(!w){toast('Allow pop-ups to print barcode labels.',true);return}w.document.write('<!doctype html><title>Preparing barcode label…</title><p style=\"font:16px Arial;padding:24px\">Preparing barcode label…</p>');try{const response=await fetch(`/api/fish/${id}/barcode.svg`,{headers:{Authorization:`Bearer ${state.token}`}});if(!response.ok)throw Error('Could not generate barcode label.');const svg=await response.text();if(!svg.trim().startsWith('<svg'))throw Error('The barcode image was not generated correctly. Please try again.');const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));const f=state.fish.find(x=>x.id==id);w.onafterprint=()=>URL.revokeObjectURL(url);w.document.open();w.document.write(`<!doctype html><html><head><meta charset=\"utf-8\"><title>${esc(f.name)} barcode label</title><style>body{font:16px Arial;text-align:center;padding:28px;color:#283d2c}.label{border:1px dashed #aaa;padding:22px;display:inline-block}img{display:block;width:340px;max-width:100%;height:auto;margin:8px auto}h2{margin:0 0 8px}.meta{font-size:13px}</style></head><body><div class=\"label\"><h2>${esc(f.name)}</h2><img src=\"${url}\" onload=\"window.focus();setTimeout(()=>window.print(),150)\" onerror=\"document.body.innerHTML='Barcode image could not be displayed.'\"><p class=\"meta\">${esc(f.barcode_type||'EAN-13')} · ${esc(f.barcode)}<br>${money(f.price_per_kg)} / kg</p></div></body></html>`);w.document.close()}catch(e){w.close();toast(e.message,true)}}
(async()=>{await loadBrand();if(state.token&&state.user){try{await api('/api/me');await start()}catch{}}else renderLogin()})();
